CREATE TABLE service_requests(id bigserial primary key,customer_id varchar(10) not null,type varchar(80) not null,raising_staff varchar(20),owning_branch varchar(10) not null,assigned_to varchar(20),status varchar(30) not null,notes text,resolution text,created_at timestamptz not null);
CREATE TABLE financial_requests(id varchar(50) primary key,kind varchar(30) not null,customer_id varchar(10) not null,original_fee_reference varchar(80),amount numeric(19,2) not null,justification varchar(500),requester varchar(20),approver varchar(20),owning_branch varchar(10),authorization_basis varchar(160),status varchar(30),pre_authorized boolean not null default false,core_reference varchar(100),requested_at timestamptz not null);
CREATE TABLE case_notes(id bigserial primary key,customer_id varchar(10),service_request_id varchar(30),visibility varchar(30),author varchar(20),text text,created_at timestamptz not null);
CREATE TABLE case_documents(id bigserial primary key,customer_id varchar(10),category varchar(30),uploader varchar(20),original_name varchar(255),content_type varchar(100),size_bytes bigint,storage_ref varchar(100),created_at timestamptz not null);
CREATE TABLE audit_events(id bigserial primary key,actor varchar(20),action varchar(100),resource_class varchar(100),record_count integer,customer_ref varchar(80),scope varchar(160),authorization_basis varchar(255),before_value text,after_value text,occurred_at timestamptz not null);
CREATE OR REPLACE RULE audit_no_update AS ON UPDATE TO audit_events DO INSTEAD NOTHING;
CREATE OR REPLACE RULE audit_no_delete AS ON DELETE TO audit_events DO INSTEAD NOTHING;
CREATE TABLE notifications(id bigserial primary key,recipient varchar(40),message varchar(500),link varchar(255),read boolean not null default false,created_at timestamptz not null);
CREATE TABLE fee_schedule(fee_code varchar(40) primary key,product_type varchar(80),currency varchar(3),amount numeric(19,2));
CREATE TABLE policy(id bigint primary key,currency varchar(3),policy_ceiling numeric(19,2),escalation_endpoint varchar(255));
CREATE TABLE outbox(id bigserial primary key,recipient varchar(160),subject varchar(255),body text,status varchar(30),created_at timestamptz not null);
CREATE TABLE password_reset_tokens(token_hash varchar(128) primary key,employee_id varchar(20),expires_at timestamptz,used_at timestamptz);
CREATE TABLE transaction_search(id bigserial primary key,account_number varchar(30),customer_id varchar(10),branch varchar(10),booking_date date,amount numeric(19,2),currency varchar(3),description varchar(255),channel varchar(40),reference varchar(80));
CREATE INDEX tx_customer_date ON transaction_search(customer_id,booking_date);

INSERT INTO policy(id,currency,policy_ceiling) VALUES(1,'GBP',100000.00);
INSERT INTO fee_schedule(fee_code,product_type,currency,amount) VALUES ('OD-DAILY','Everyday Current','GBP',15.00),('CHAPS','Current Accounts','GBP',25.00),('CARD-REPLACE','Debit Card','GBP',5.00),('INTL-CARD','Debit Card','GBP',2.75);
INSERT INTO service_requests(customer_id,type,raising_staff,owning_branch,assigned_to,status,notes,resolution,created_at)
SELECT 'C'||lpad(((n-1)%40+1)::text,4,'0'), CASE n%4 WHEN 0 THEN 'Address evidence' WHEN 1 THEN 'Payment query' WHEN 2 THEN 'Bereavement support' ELSE 'Account maintenance' END,'EMP'||lpad(((n-1)%17+1)::text,3,'0'),'B0'||(((n-1)%9)+1),CASE WHEN n%8=0 THEN NULL ELSE 'EMP003' END,CASE n%10 WHEN 0 THEN 'open' WHEN 1 THEN 'assigned' WHEN 2 THEN 'in_progress' WHEN 3 THEN 'escalated' WHEN 4 THEN 'pending_customer' WHEN 5 THEN 'resolved' WHEN 6 THEN 'closed' WHEN 7 THEN 'reopened' ELSE 'in_progress' END,'Seeded servicing history '||n,CASE WHEN n%10 IN(5,6) THEN 'Customer request completed' ELSE NULL END,now()-(n||' hours')::interval FROM generate_series(1,32)n;
INSERT INTO financial_requests(id,kind,customer_id,amount,justification,requester,approver,owning_branch,authorization_basis,status,core_reference,requested_at)
SELECT 'FIN-'||lpad(n::text,3,'0'),CASE WHEN n%2=0 THEN 'FEE_REVERSAL' ELSE 'LIMIT_OVERRIDE' END,'C'||lpad(((n-1)%20+1)::text,4,'0'),(n*35)::numeric(19,2),'Customer servicing exception '||n,'EMP002',CASE WHEN n%5=2 THEN 'EMP003' ELSE NULL END,'B0'||(((n-1)%9)+1),CASE WHEN n%5=0 THEN 'above_threshold' WHEN n%5 IN(1,2) THEN 'below_threshold' ELSE 'workflow' END,CASE n%5 WHEN 0 THEN 'pending_approval' WHEN 1 THEN 'approved' WHEN 2 THEN 'applied' WHEN 3 THEN 'declined' ELSE 'expired' END,CASE WHEN n%5=2 THEN 'CORE-FIN-'||n ELSE NULL END,now()-(n||' days')::interval FROM generate_series(1,22)n;
INSERT INTO case_notes(customer_id,service_request_id,visibility,author,text,created_at) SELECT 'C'||lpad(((n-1)%12+1)::text,4,'0'),n::text,CASE WHEN n%2=0 THEN 'internal' ELSE 'customer_disclosable' END,'EMP002','Follow-up note supplied by the servicing team. Reference '||n,now()-(n||' hours')::interval FROM generate_series(1,18)n;
INSERT INTO notifications(recipient,message,link,read,created_at) VALUES('EMP003','A fee reversal is waiting for approval','/approvals',false,now()),('EMP004','An escalated request entered your region','/requests',false,now());
INSERT INTO audit_events(actor,action,resource_class,record_count,customer_ref,scope,authorization_basis,before_value,after_value,occurred_at) SELECT 'EMP003','REQUEST_TRANSITION','service_request',1,md5(('C'||n)::text),'B01','workflow','assigned','in_progress',now()-(n||' hours')::interval FROM generate_series(1,25)n;
INSERT INTO transaction_search(account_number,customer_id,branch,booking_date,amount,currency,description,channel,reference)
SELECT '100200'||lpad((((n-1)%40)+1)::text,4,'0')||'0','C'||lpad((((n-1)%40)+1)::text,4,'0'),'B0'||((((n-1)%40)%9)+1),current_date-(n%180),CASE WHEN n%3=0 THEN -(n%125+1)::numeric ELSE (n%500+10)::numeric END + .25,'GBP',CASE WHEN n%4=0 THEN 'Northstar supermarket' WHEN n%4=1 THEN 'Salary payment' WHEN n%4=2 THEN 'Energy direct debit' ELSE 'Online transfer' END,CASE WHEN n%2=0 THEN 'CARD' ELSE 'FASTER_PAYMENT' END,'TX-'||lpad(n::text,6,'0') FROM generate_series(1,480)n;
